sp_widget.css:
/* Stile per il contenitore generico delle "cards" o "panels" */
/* Applicheremo questo allo stesso modo in cui il .panel è stato applicato alla prima tabella */
.card {
  border-radius: 12px; /* Angoli arrotondati per il contenitore */
  border: 1px solid #dcdcdc; /* Bordo sottile */
  padding: 20px; /* Spazio interno */
  background-color: #fefefe; /* Sfondo quasi bianco */
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.03); /* Leggera ombra */
}

/* Stili comuni per tutte le tabelle con la classe .table */
/* Sovrascriviamo o estendiamo le classi di framework come Bootstrap */
table.table {
  border: 1px solid #e0e0e0; /* Bordo esterno della tabella */
  border-radius: 12px; /* Angoli arrotondati della tabella */
  border-collapse: separate; /* Necessario per border-radius e border-spacing */
  border-spacing: 0; /* Rimuove lo spazio tra le celle */
  overflow: hidden; /* Importante per applicare border-radius ai contenuti */
  width: 100%; /* Larghezza completa */
  background-color: #ffffff; /* Sfondo bianco per la tabella */
}

/* Intestazione della tabella */
table.table thead {
  background-color: #f3f7fb; /* Sfondo azzurro molto chiaro per l'header */
}

/* Cella di intestazione (<th>) */
table.table th {
  padding: 12px 16px; /* Spazio interno */
  font-weight: 600; /* Grassetto per il testo */
  text-align: left; /* Allineamento a sinistra */
  color: #2f4f4f; /* Colore scuro per il testo */
  border-bottom: 1px solid #f0f0f0; /* Bordo inferiore per separare l'header dalle righe */
}

/* Celle del corpo della tabella (<td>) */
table.table td {
  padding: 12px 16px; /* Spazio interno */
  border-bottom: 1px solid #f0f0f0; /* Bordo inferiore per separare le righe */
  color: #333; /* Colore testo scuro */
}

/* Riga alternata (righe pari) */
table.table tbody tr:nth-child(even) {
  background-color: #fafafa; /* Sfondo grigio molto chiaro */
}

/* Stile per il titolo della sezione (h3/h4) */
h3, h4 {
  font-size: 20px; /* Dimensione del font */
  margin-bottom: 20px; /* Margine inferiore */
  display: flex; /* Per allineare testo e icona (se presente) */
  align-items: center; /* Allineamento verticale */
  color: #007863; /* Colore verde scuro */
}

/* Stili per le label di stato (Disponibilità, Annullata) */
.text-success,
.text-danger {
  font-size: 14px;
  padding: 5px 10px;
  border-radius: 12px;
  display: inline-block;
  min-width: 60px;
  text-align: center;
  filter: none !important; /* Rimuove eventuali filtri predefiniti */
}

.text-success {
  background-color: #b7e4c7 !important; /* Verde chiaro per "Disponibile" */
  color: #1b4332 !important; /* Testo verde scuro */
}

.text-danger {
  background-color: #f8d7da !important; /* Rosso chiaro per "Non disponibile" o "Annullata" */
  color: #721c24 !important; /* Testo rosso scuro */
}

/* Stile specifico per le righe "Annullata" */
/* Se vuoi che l'intera riga sia rossa e non solo lo stato */
tr.text-danger {
  /* Puoi aggiungere qui stili per la riga completa se necessario,
     ma di solito è meglio lasciare che sia il .text-danger sulla cella di stato
     a gestire il colore per chiarezza.
     Se volessi un background per l'intera riga, ad esempio:
     background-color: #fde7ea;
  */
}

/* Rimuoviamo gli stili per .table-bordered di Bootstrap per mantenere il nostro look */
/* In questo modo i bordi singoli delle celle non appariranno */
table.table.table-bordered th,
table.table.table-bordered td {
  border: none; /* Rimuove i bordi predefiniti di table-bordered */
}

sp_widget.script:
(function() {
    var userSysId = gs.getUserID();
    var grPrenotazioni = new GlideRecord('x_1763019_furgonch_prenotazione');

    var gruppoOperatoriId = '5ccf0ffcc3a12210e9a97205e4013131';
    var gruppoClientiId = '8f5f47fcc3a12210e9a97205e40131d0';

    var gruppiUtente = [];
    var grUserGroup = new GlideRecord('sys_user_grmember');
    grUserGroup.addQuery('user', userSysId);
    grUserGroup.query();
    while (grUserGroup.next()) {
        gruppiUtente.push(grUserGroup.group.toString());
    }

    data.prenotazioni = [];

    if (gruppiUtente.indexOf(gruppoOperatoriId) !== -1) {
        grPrenotazioni.query();
    } else if (gruppiUtente.indexOf(gruppoClientiId) !== -1) {
        grPrenotazioni.addQuery('cliente', userSysId);
        grPrenotazioni.query();
    }

    while (grPrenotazioni.next()) {
        var costoTotale = grPrenotazioni.costo_totale.getDisplayValue();

        // Se la prenotazione è annullata ed è assicurata, il costo è 0
        if (grPrenotazioni.stato_prenotazione == 'Annullata' && grPrenotazioni.assicurata == true) {
            costoTotale = '0.00';
        }

        data.prenotazioni.push({
            id_prenotazione: grPrenotazioni.getDisplayValue('id_prenotazione'),
            utente: grPrenotazioni.cliente.getDisplayValue(),
            categoria: grPrenotazioni.veicolo.categoria.getDisplayValue(),
            marca: grPrenotazioni.marca.getDisplayValue(),
            modello: grPrenotazioni.modello.getDisplayValue(),
            dataInizio: grPrenotazioni.getDisplayValue('data_prenotazione'),
            dataFine: grPrenotazioni.getDisplayValue('data_restituzione'),
            stato: grPrenotazioni.getDisplayValue('stato_prenotazione'),
            assicurata: grPrenotazioni.assicurata ? 'Sì' : 'No',
            costoTotale: costoTotale,
			creditoRimborsato:grPrenotazioni.credito_rimborsato.getDisplayValue()
        });
    }
})();
